def binary_search(a, x):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if a[mid] == x:
            return mid
        if a[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

a = [2, 5, 8, 12, 16, 23]
print(binary_search(a, 16))
print(binary_search(a, 7))
